<script setup lang="ts">
import { onMounted, reactive, shallowRef } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import * as equipmentApi from '../../api/equipment'
import * as repairApi from '../../api/repair'
import { useAuthStore } from '../../stores/auth'
import { priorityLabel, priorityType, repairPriorities, workOrderStatusLabel, workOrderStatusType } from '../../utils/workOrderStatus'

const route=useRoute();const router=useRouter();const auth=useAuthStore();const loading=shallowRef(false);const submitting=shallowRef(false)
const records=shallowRef<any[]>([]);const equipment=shallowRef<any[]>([]);const total=shallowRef(0)
const query=reactive<any>({requestNo:'',priority:null,status:null,page:1,size:10})
const form=reactive<any>({equipmentId:null,priority:'NORMAL',faultDescription:'',source:'PC'})
async function loadEquipment(){const response=await equipmentApi.page({status:'RUNNING',page:1,size:100});equipment.value=response.data.records}
async function load(){loading.value=true;try{const response=await repairApi.page(query);records.value=response.data.records;total.value=response.data.total}catch(e:any){ElMessage.error(e.response?.data?.message||'报修记录加载失败')}finally{loading.value=false}}
async function submit(){if(!form.equipmentId||!form.faultDescription.trim())return ElMessage.warning('请选择设备并填写故障描述');submitting.value=true;try{const response=await repairApi.create({...form,faultDescription:form.faultDescription.trim()});ElMessage.success(`报修成功，已生成工单 ${response.data.workOrderNo}`);Object.assign(form,{equipmentId:null,priority:'NORMAL',faultDescription:'',source:'PC'});await Promise.all([loadEquipment(),load()]);router.push(`/work-orders/${response.data.workOrderId}`)}catch(e:any){ElMessage.error(e.response?.data?.message||'报修提交失败')}finally{submitting.value=false}}
async function cancel(row:any){try{const {value}=await ElMessageBox.prompt('请输入取消原因；确认设备正常将恢复运行，否则请输入“设备停用”并在下一步选择停用。','取消报修',{inputPattern:/\S+/,inputErrorMessage:'取消原因不能为空',type:'warning'});const target=await ElMessageBox.confirm('取消后设备是否确认恢复运行？选择“停用设备”将设备置为停用。','设备状态处置',{confirmButtonText:'恢复运行',cancelButtonText:'停用设备',distinguishCancelAndClose:true,type:'warning'}).then(()=> 'RUNNING').catch((action:any)=>{if(action==='cancel')return 'STOPPED';throw action});await repairApi.cancel(row.id,{reason:value,equipmentTargetStatus:target});ElMessage.success('报修及关联工单已取消');await Promise.all([loadEquipment(),load()])}catch(e:any){if(e!=='close'&&e!=='cancel')ElMessage.error(e.response?.data?.message||'取消失败')}}
function search(){query.page=1;load()}
onMounted(async()=>{const equipmentId=Number(route.query.equipmentId);if(equipmentId)form.equipmentId=equipmentId;if(route.query.source==='QR')form.source='QR';await Promise.all([loadEquipment(),load()])})
</script>

<template><section class="module-page"><header class="module-header"><div><p class="eyebrow">FAULT REPORTING</p><h1>故障报修</h1><p>提交后自动生成唯一维修工单，并将设备置为故障状态。</p></div></header>
<el-card v-permission="'repair:create'" shadow="never" class="repair-create-card"><template #header><b>{{form.source==='QR'?'扫码报修':'创建故障报修'}}</b></template><el-form label-width="92px"><el-form-item label="故障设备" required><el-select v-model="form.equipmentId" filterable placeholder="请选择运行中的设备" style="width:100%"><el-option v-for="item in equipment" :key="item.id" :label="`${item.equipmentNo} · ${item.equipmentName}`" :value="item.id"/></el-select></el-form-item><el-form-item label="故障等级" required><el-radio-group v-model="form.priority"><el-radio-button v-for="(item,key) in repairPriorities" :key="key" :value="key">{{item.label}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="故障描述" required><el-input v-model="form.faultDescription" type="textarea" :rows="4" maxlength="5000" show-word-limit placeholder="请描述故障现象、发生时间和现场情况"/></el-form-item><el-form-item><el-button type="danger" :loading="submitting" @click="submit">提交报修并生成工单</el-button><span class="form-tip">报修人由当前登录账号自动确定</span></el-form-item></el-form></el-card>
<el-card shadow="never"><template #header><b>报修记录</b></template><el-form inline class="compact-filter"><el-form-item label="报修编号"><el-input v-model="query.requestNo" clearable/></el-form-item><el-form-item label="等级"><el-select v-model="query.priority" clearable><el-option v-for="(item,key) in repairPriorities" :key="key" :label="item.label" :value="key"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="已转工单" value="CONVERTED"/><el-option label="已取消" value="CANCELLED"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button></el-form-item></el-form><el-table v-loading="loading" :data="records" stripe><el-table-column prop="requestNo" label="报修编号" min-width="205"/><el-table-column label="设备" min-width="190"><template #default="{row}"><b>{{row.equipmentName}}</b><small class="table-subtitle">{{row.equipmentNo}}</small></template></el-table-column><el-table-column label="等级" width="90"><template #default="{row}"><el-tag :type="priorityType(row.priority)">{{priorityLabel(row.priority)}}</el-tag></template></el-table-column><el-table-column prop="faultDescription" label="故障描述" min-width="240" show-overflow-tooltip/><el-table-column prop="reporterName" label="报修人" width="100"/><el-table-column label="工单状态" width="110"><template #default="{row}"><el-tag v-if="row.workOrderStatus" :type="workOrderStatusType(row.workOrderStatus)">{{workOrderStatusLabel(row.workOrderStatus)}}</el-tag></template></el-table-column><el-table-column prop="reportedAt" label="报修时间" width="170"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button v-if="row.workOrderId" link type="primary" @click="router.push(`/work-orders/${row.workOrderId}`)">查看工单</el-button><el-button v-if="['PENDING_ASSIGN','ASSIGNED'].includes(row.workOrderStatus)" v-permission="'repair:cancel'" link type="danger" @click="cancel(row)">取消</el-button></template></el-table-column></el-table><div class="pagination-row"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></el-card></section></template>
